// Forearth Studio service worker. Generated by build/build.mjs — edit build/sw.template.js instead.
// App shell and static files are cached for instant, offline-tolerant start-up.
// Data never passes through this cache: /api, /auth and /admin always go to the network.
const VERSION = 'ec3f715abc';
const SHELL = 'fs-shell-' + VERSION;
const FONTS = 'fs-fonts';
const PRECACHE = ["/login","/login.js","/manifest.webmanifest","/favicon.ico","/icons/apple-touch-icon.png","/icons/favicon-16.png","/icons/favicon-32.png","/icons/icon-192.png","/icons/icon-512.png","/icons/icon-maskable-512.png","/icons/mark-dark.png","/icons/mark-light.png"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(SHELL).then(c => c.addAll(PRECACHE)).catch(() => {}).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('fs-shell-') && k !== SHELL).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});

const OFFLINE = `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Offline · Forearth Studio</title>
<body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#101311;color:#ebe8dd;font:15px/1.5 system-ui,sans-serif;text-align:center;padding:24px">
<div><div style="font-weight:700;letter-spacing:.2em;margin-bottom:10px">FOREARTH</div>You are offline. Connect to the internet and try again.<br><br>
<button onclick="location.reload()" style="font:inherit;padding:8px 16px;border-radius:4px;border:1px solid #3b433d;background:none;color:inherit">Try again</button></div></body>`;

function withTimeout(p, ms) { return Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms))]); }

self.addEventListener('fetch', e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== 'GET') return;

  if (url.origin === 'https://fonts.googleapis.com' || url.origin === 'https://fonts.gstatic.com') {
    e.respondWith(caches.open(FONTS).then(async c => { const hit = await c.match(req); if (hit) return hit; const res = await fetch(req); if (res.ok) c.put(req, res.clone()); return res; }));
    return;
  }
  if (url.origin !== location.origin) return;
  if (/^\/(api|auth|admin)\//.test(url.pathname)) return;

  if (req.mode === 'navigate') {
    const isApp = url.pathname === '/' || url.pathname === '/index.html';
    e.respondWith((async () => {
      try {
        const res = await withTimeout(fetch(req), isApp ? 5000 : 8000);
        if (isApp && res.ok && !res.redirected) (await caches.open(SHELL)).put('/', res.clone());
        return res;
      } catch (err) {
        const c = await caches.open(SHELL);
        return (await c.match(isApp ? '/' : url.pathname)) || (await c.match('/login')) || new Response(OFFLINE, { headers: { 'content-type': 'text/html; charset=utf-8' } });
      }
    })());
    return;
  }

  if (/^\/(app|icons)\//.test(url.pathname) || /^\/(login\.js|manifest\.webmanifest|favicon\.ico)$/.test(url.pathname)) {
    e.respondWith(caches.open(SHELL).then(async c => {
      const hit = await c.match(req);
      const net = fetch(req).then(res => { if (res.ok && res.status === 200) c.put(req, res.clone()); return res; }).catch(() => null);
      return hit || (await net) || new Response('', { status: 504 });
    }));
  }
});
